<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { Bell, Clock3, GanttChart, AlertCircle, CheckCircle2, ChevronRight, CircleHelp, ClipboardList, FileText, FolderOpen, LayoutDashboard, NotebookPen, Plus, Search, Settings2, Trash2, X } from 'lucide-vue-next'
import Modal from './components/Modal.vue'
import Pager from './components/Pager.vue'
import RecordModal from './components/RecordModal.vue'
import Lightbox from './components/Lightbox.vue'
import HighlightText from './components/HighlightText.vue'
import TodayPage from './pages/TodayPage.vue'
import ProjectsPage from './pages/ProjectsPage.vue'
import TasksPage from './pages/TasksPage.vue'
import RecordsPage from './pages/RecordsPage.vue'
import WorklogsPage from './pages/WorklogsPage.vue'
import IssuesPage from './pages/IssuesPage.vue'
import SettingsPage from './pages/SettingsPage.vue'
import TrashPage from './pages/TrashPage.vue'
import TimeEntriesPage from './pages/TimeEntriesPage.vue'
import RemindersPage from './pages/RemindersPage.vue'
import ProgressPage from './pages/ProgressPage.vue'
import CompactPage from './pages/CompactPage.vue'
import ProjectJournalPage from './pages/ProjectJournalPage.vue'
import ExportsPage from './pages/ExportsPage.vue'
import MeetingMinutesPage from './pages/MeetingMinutesPage.vue'
import PlanVersionsPage from './pages/PlanVersionsPage.vue'
import RequirementsPage from './pages/RequirementsPage.vue'
import MemberWorkspacePage from './pages/MemberWorkspacePage.vue'
import { api, loadProjects, messageOf, notify, projectName, query, ui } from './api'
import type { Attachment, Page, RecordEntry, SearchHit } from './types'
const nav=[{id:'today',name:'今日',icon:LayoutDashboard},{id:'projects',name:'项目',icon:FolderOpen},{id:'tasks',name:'任务与 WBS',icon:ClipboardList},{id:'progress',name:'进度视图',icon:GanttChart},{id:'records',name:'现场记录',icon:NotebookPen},{id:'worklogs',name:'工作日志',icon:FileText},{id:'time-entries',name:'工时',icon:Clock3},{id:'reminders',name:'任务提醒',icon:Bell},{id:'issues',name:'问题台账',icon:CircleHelp},{id:'trash',name:'回收站',icon:Trash2},{id:'settings',name:'设置与备份',icon:Settings2}]
function hashPage(){if(location.protocol==='https:')return 'team-member';const id=location.hash.replace('#/','').split('?')[0];return ['compact','project-journal','meeting-minutes','exports','plan-versions','requirements','team-member'].includes(id||'')?id!:nav.some(n=>n.id===id)?id!:'today'}
let handledHash=location.hash
const page=ref(hashPage()),revision=ref(0),ready=ref(false),bootError=ref(''),recordOpen=ref(false),recordProject=ref(''),editingRecord=ref<RecordEntry>(),images=ref<Attachment[]>([]),imageIndex=ref(0),imageOpen=ref(false),searchOpen=ref(false),searchText=ref(''),searching=ref(false),searchError=ref(''),hits=ref<SearchHit[]>([]),searchTotal=ref(0),searchOffset=ref(0),activeHit=ref(0),taskProject=ref(''),firstRun=ref(false),operator=ref(''),setupSaving=ref(false),setupError=ref('')
const activePage=ref<{openEntity?:(id:string)=>Promise<void>;canLeave?:()=>boolean}>()
const activeNav=computed(()=>['project-journal','meeting-minutes','exports'].includes(page.value)?'worklogs':['plan-versions','requirements'].includes(page.value)?'tasks':page.value)
const pageName=computed(()=>nav.find(n=>n.id===activeNav.value)?.name||'今日');const searchLimit=30;let searchTimer:ReturnType<typeof setTimeout>|undefined;let searchRequest=0;const cursors=new Map<number,string>()
const order=['projects','tasks','records','issues','worklogs','time_entries','reminders','team_daily_entries','project_daily_logs','meeting_minutes','plan_versions','requirements'];const groups=computed(()=>order.map(kind=>({kind,label:typeName(kind),items:hits.value.filter(h=>h.entity_type.replace(/s$/,'')===kind.replace(/s$/,''))})).filter(g=>g.items.length));const orderedHits=computed(()=>groups.value.flatMap(g=>g.items))
async function navigate(id:string,entityId=''){if(page.value!==id&&activePage.value?.canLeave&&!activePage.value.canLeave())return false;page.value=id;handledHash=`#/${id}${entityId?'?id='+encodeURIComponent(entityId):''}`;location.hash=handledHash;await nextTick();if(entityId)await activePage.value?.openEntity?.(entityId);document.querySelector('main')?.scrollTo(0,0);return true}
async function onHash(){if(location.hash===handledHash)return;const wasMember=page.value==='team-member',next=hashPage(),id=new URLSearchParams(location.hash.split('?')[1]||'').get('id');if(page.value!==next){if(activePage.value?.canLeave&&!activePage.value.canLeave()){location.hash=handledHash;return}page.value=next;await nextTick()}handledHash=location.hash;if(wasMember&&next!=='team-member'){await boot();return;}if(id)await activePage.value?.openEntity?.(id)}
function quickNote(project=''){editingRecord.value=undefined;recordProject.value=project;recordOpen.value=true}
function editRecord(record:RecordEntry){editingRecord.value=record;recordOpen.value=true}
async function openRecord(id:string){try{editRecord(await api<RecordEntry>(`/api/records/${id}`))}catch(e){notify(messageOf(e),true)}}
function showImages(a:Attachment,list:Attachment[]=[a]){images.value=list;imageIndex.value=Math.max(0,list.findIndex(item=>item.id===a.id));imageOpen.value=true}
function changed(){revision.value++;void loadProjects().catch(e=>notify(messageOf(e),true))}
function openTasks(id:string){taskProject.value=id;void navigate('tasks')}
async function doSearch(offset=0){searchOffset.value=offset;const q=searchText.value.trim(),request=++searchRequest;if(!q){hits.value=[];searchTotal.value=0;searching.value=false;return}searching.value=true;searchError.value='';try{const data=await api<Page<SearchHit>>(`/api/search?${query({q,limit:searchLimit,...(cursors.has(offset)?{cursor:cursors.get(offset)}:{offset})})}`);if(request===searchRequest){hits.value=data.items;searchTotal.value=data.total;activeHit.value=0;if(data.next_cursor)cursors.set(offset+searchLimit,data.next_cursor)}}catch(e){if(request===searchRequest)searchError.value=messageOf(e)}finally{if(request===searchRequest)searching.value=false}}
function searchInput(){clearTimeout(searchTimer);cursors.clear();searchTimer=setTimeout(()=>void doSearch(),200)}
async function openHit(hit:SearchHit){const type=({time_entries:'time_entry',team_daily_entries:'team_daily_entry',project_daily_logs:'project_daily_log',meeting_minutes:'meeting_minute',plan_versions:'plan_version'} as Record<string,string>)[hit.entity_type]||hit.entity_type.replace(/s$/,'');const target:Record<string,string>={project:'projects',task:'tasks',record:'records',issue:'issues',worklog:'worklogs',time_entry:'time-entries',reminder:'reminders',team_daily_entry:'project-journal',project_daily_log:'project-journal',meeting_minute:'meeting-minutes',plan_version:'plan-versions',requirement:'requirements'};searchOpen.value=false;if(type==='record'){try{editRecord(await api<RecordEntry>(`/api/records/${hit.entity_id}`))}catch(e){notify(messageOf(e),true)}}else if(target[type])await navigate(target[type]!,type==='team_daily_entry'?'team:'+hit.entity_id:hit.entity_id)}
function searchKey(event:KeyboardEvent){if(event.isComposing||searching.value)return;if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const count=orderedHits.value.length;if(count){activeHit.value=(activeHit.value+(event.key==='ArrowDown'?1:-1)+count)%count;void nextTick(()=>document.getElementById(`search-result-${activeHit.value}`)?.scrollIntoView({block:'nearest'}))}}else if(event.key==='Enter'&&orderedHits.value.length){event.preventDefault();void openHit(orderedHits.value[activeHit.value]!)} }
function hitIndex(hit:SearchHit){return orderedHits.value.indexOf(hit)}
function typeName(type:string){return ({project:'项目',task:'任务',record:'记录',issue:'问题',worklog:'日志',time_entry:'工时',reminder:'提醒',team_daily_entry:'人员工作记录',project_daily_log:'项目日志',meeting_minute:'会议纪要',plan_version:'计划版本',requirement:'需求'} as Record<string,string>)[({time_entries:'time_entry',team_daily_entries:'team_daily_entry',project_daily_logs:'project_daily_log',meeting_minutes:'meeting_minute',plan_versions:'plan_version'} as Record<string,string>)[type]||type.replace(/s$/,'')]||type}
function keydown(event:KeyboardEvent){if(!ready.value||page.value==='team-member')return;if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchOpen.value=true}else if(event.altKey&&event.key.toLowerCase()==='n'){event.preventDefault();if(!recordOpen.value&&!searchOpen.value)quickNote()}}
async function boot(){if(page.value==='team-member'){ready.value=true;return;}ready.value=false;bootError.value='';try{const settings=await api<Record<string,string>>('/api/settings');if(!settings.dataset_id)throw new Error('服务未提供数据集标识，无法安全隔离本地草稿，请升级服务后重试');ui.datasetId=settings.dataset_id;ui.dataDir=settings.data_dir||'';operator.value=settings.operator||'本人';ui.operator=operator.value;firstRun.value=settings.setup_completed!=='1';await loadProjects();ready.value=true;await nextTick();const id=new URLSearchParams(location.hash.split('?')[1]||'').get('id');if(id)await activePage.value?.openEntity?.(id)}catch(e){bootError.value=messageOf(e)}}
async function finishSetup(){setupSaving.value=true;setupError.value='';try{await api('/api/settings',{method:'PUT',body:JSON.stringify({operator:operator.value,setup_completed:'1'})});ui.operator=operator.value;firstRun.value=false;notify('工作空间已就绪')}catch(e){setupError.value=messageOf(e)}finally{setupSaving.value=false}}
onMounted(()=>{window.addEventListener('hashchange',onHash);window.addEventListener('keydown',keydown);void boot()});onUnmounted(()=>{window.removeEventListener('hashchange',onHash);window.removeEventListener('keydown',keydown);clearTimeout(searchTimer)})
</script>
<template><MemberWorkspacePage ref="activePage" v-if="page==='team-member'"/><div v-else class="app-shell"><aside v-if="page!=='compact'" class="sidebar"><a class="brand" href="#/today" @click.prevent="navigate('today')" aria-label="ProjNote 今日工作台"><span class="brand-mark"><i/><i/></span><div><strong>ProjNote</strong><span>项目管理工作台</span></div></a><div class="nav-group-label">工作空间</div><nav aria-label="主导航"><a v-for="item in nav" :key="item.id" :href="`#/${item.id}`" :class="{active:activeNav===item.id,'mobile-settings':item.id==='settings'}" :aria-current="activeNav===item.id?'page':undefined" @click.prevent="navigate(item.id)"><component :is="item.icon" :size="19"/><span>{{item.name}}</span><ChevronRight v-if="activeNav===item.id" :size="15" class="nav-current"/></a></nav><div class="sidebar-bottom"><a class="settings-nav" href="#/settings" :class="{active:page==='settings'}" @click.prevent="navigate('settings')"><Settings2 :size="18"/>设置与备份</a><div class="local-space"><span class="local-dot"/><div><strong>本地工作空间</strong><span>资料保存在这台电脑</span></div></div></div></aside><div class="workspace" :class="{'compact-workspace':page==='compact'}"><header v-if="page!=='compact'" class="topbar"><div class="breadcrumb">我的工作空间<ChevronRight :size="14"/><strong>{{pageName}}</strong></div><div class="top-actions"><button class="search-launcher" :disabled="!ready" @click="searchOpen=true"><Search :size="16"/><span>搜索项目、任务、记录</span><kbd>Ctrl K</kbd></button><button class="button primary quick-button" :disabled="!ready" @click="quickNote()"><Plus :size="17"/>速记<kbd>Alt N</kbd></button></div></header><main id="main-content" tabindex="-1"><div v-if="bootError" class="error-banner" role="alert">{{bootError}}<button class="button small" @click="boot">重新连接</button></div><p v-else-if="!ready" class="loading-message">正在连接本地工作空间…</p><template v-else><CompactPage ref="activePage" v-if="page==='compact'" :revision="revision" @changed="changed" @record="quickNote" @full="navigate('today')"/><TodayPage v-else-if="page==='today'" :revision="revision" @record="quickNote()" @navigate="navigate" @image="showImages" @edit="editRecord" @changed="changed"/><ProjectsPage ref="activePage" v-else-if="page==='projects'" :revision="revision" @changed="changed" @tasks="openTasks"/><TasksPage ref="activePage" v-else-if="page==='tasks'" :revision="revision" :initial-project="taskProject" @changed="changed"/><PlanVersionsPage ref="activePage" v-else-if="page==='plan-versions'" :revision="revision" @changed="changed"/><RequirementsPage ref="activePage" v-else-if="page==='requirements'" :revision="revision" @changed="changed"/><ProgressPage ref="activePage" v-else-if="page==='progress'" :revision="revision" @changed="changed" @task="navigate('tasks',$event)"/><ProjectJournalPage ref="activePage" v-else-if="page==='project-journal'" :revision="revision" @changed="changed"/><RecordsPage ref="activePage" v-else-if="page==='records'" :revision="revision" @record="quickNote" @image="showImages" @edit="editRecord" @changed="changed"/><MeetingMinutesPage ref="activePage" v-else-if="page==='meeting-minutes'" :revision="revision" @changed="changed"/><ExportsPage ref="activePage" v-else-if="page==='exports'" :revision="revision"/><WorklogsPage ref="activePage" v-else-if="page==='worklogs'" :revision="revision" @changed="changed"/><IssuesPage ref="activePage" v-else-if="page==='issues'" :revision="revision" @changed="changed"/><TimeEntriesPage ref="activePage" v-else-if="page==='time-entries'" :revision="revision" @changed="changed"/><RemindersPage ref="activePage" v-else-if="page==='reminders'" :revision="revision" @changed="changed" @record="openRecord"/><TrashPage ref="activePage" v-else-if="page==='trash'" :revision="revision" @changed="changed"/><SettingsPage ref="activePage" v-else @changed="changed"/></template></main></div><Transition name="toast"><div v-if="ui.toast" class="toast" :class="{error:ui.error}" :role="ui.error?'alert':'status'"><AlertCircle v-if="ui.error" :size="19"/><CheckCircle2 v-else :size="19"/><span>{{ui.toast}}</span><button aria-label="关闭提示" @click="ui.toast=''"><X :size="16"/></button></div></Transition><RecordModal :open="recordOpen" :project-id="recordProject" :record="editingRecord" @close="recordOpen=false" @saved="changed"/><Lightbox :open="imageOpen" :images="images" :initial="imageIndex" @close="imageOpen=false"/><Modal :open="searchOpen" title="搜索工作空间" wide @close="searchOpen=false"><div class="modal-body search-body"><form class="search-form" @submit.prevent="doSearch()"><Search :size="20"/><input v-model="searchText" autofocus placeholder="项目、任务、记录、问题、日志…" aria-label="全局搜索关键词" aria-controls="search-results" :aria-activedescendant="orderedHits.length?`search-result-${activeHit}`:undefined" @input="searchInput" @keydown="searchKey"/><button class="button primary small" type="submit">搜索</button></form><p class="input-hint">↑ ↓ 选择结果 · Enter 打开详情 · Esc 关闭</p><p v-if="searchError" class="form-error" role="alert">{{searchError}}</p><p v-else-if="searching" class="loading-message">正在搜索…</p><div v-else-if="!searchText.trim()" class="search-empty">输入关键词，查找工作空间中的内容。</div><div v-else-if="!hits.length" class="search-empty">没有找到相关内容，请换一个关键词。</div><div v-else id="search-results" class="search-results grouped-search" role="listbox" aria-label="搜索结果"><section v-for="group in groups" :key="group.kind"><h3>{{group.label}} <span>{{group.items.length}}</span></h3><button v-for="hit in group.items" :id="`search-result-${hitIndex(hit)}`" :key="`${hit.entity_type}-${hit.entity_id}`" role="option" :aria-selected="activeHit===hitIndex(hit)" :class="{selected:activeHit===hitIndex(hit)}" @mouseenter="activeHit=hitIndex(hit)" @click="openHit(hit)"><div><strong><HighlightText :text="hit.title||'无标题记录'" :query="searchText"/></strong><p><HighlightText :text="hit.body" :query="searchText"/></p><small>{{hit.project_id?projectName(hit.project_id):'工作空间'}}</small></div><ChevronRight :size="17"/></button></section></div><Pager :offset="searchOffset" :limit="searchLimit" :total="searchTotal" @change="doSearch"/></div></Modal><Modal :open="firstRun&&ready" title="设置你的本地工作空间" @close="firstRun=false"><form class="modal-body" @submit.prevent="finishSetup"><p class="onboarding-intro">先确认资料放在哪里，以及操作记录中使用的姓名。</p><label>操作人<input v-model="operator" required maxlength="80" autofocus placeholder="你的姓名或称呼"/></label><div class="directory-explainer"><strong>当前数据目录</strong><code>{{ui.dataDir||'请在设置中查看实际路径'}}</code><p>数据库、图片和备份保存在此目录。关闭浏览器不会停止服务；更换目录前先在「设置与备份」生成停服迁移指令。</p></div><p class="standard-label">已确认：GJB5000B 二级，证据模板待核对。</p><p v-if="setupError" class="form-error" role="alert">{{setupError}}</p><div class="modal-footer"><button type="button" class="button subtle" @click="firstRun=false">稍后设置</button><button class="button primary" :disabled="setupSaving">{{setupSaving?'正在保存…':'开始使用'}}</button></div></form></Modal></div></template>
